/**
 * Files the pipeline derives from a grant's document (raw-text.txt, summary.json, questions.json),
 * stored under `<grant>/` in ARTIFACTS_BUCKET. They live outside the grant bucket because the
 * Knowledge Base indexes that whole bucket. Reads fall back to the grant bucket for files written
 * before the move.
 */

import {
  GetObjectCommand,
  PutObjectCommand,
  ListObjectsV2Command,
  CopyObjectCommand,
  DeleteObjectsCommand,
} from "@aws-sdk/client-s3";

export function artifactsBucket() {
  const bucket = process.env.ARTIFACTS_BUCKET;
  if (!bucket) throw new Error("ARTIFACTS_BUCKET is not set");
  return bucket;
}

export function isMissingObject(error) {
  return error?.name === "NoSuchKey" || error?.$metadata?.httpStatusCode === 404;
}

export async function getArtifact(s3, key, legacyBucket = process.env.BUCKET) {
  try {
    return await s3.send(new GetObjectCommand({ Bucket: artifactsBucket(), Key: key }));
  } catch (error) {
    if (!legacyBucket || !isMissingObject(error)) throw error;
    return s3.send(new GetObjectCommand({ Bucket: legacyBucket, Key: key }));
  }
}

export async function readArtifactText(s3, key, legacyBucket = process.env.BUCKET) {
  const response = await getArtifact(s3, key, legacyBucket);
  const chunks = [];
  for await (const chunk of response.Body) chunks.push(chunk);
  return Buffer.concat(chunks).toString("utf8");
}

export function putArtifact(s3, key, body, contentType) {
  return s3.send(
    new PutObjectCommand({ Bucket: artifactsBucket(), Key: key, Body: body, ContentType: contentType })
  );
}

async function listArtifactKeys(s3, grantName) {
  const bucket = artifactsBucket();
  const keys = [];
  let continuationToken;
  do {
    const listed = await s3.send(
      new ListObjectsV2Command({ Bucket: bucket, Prefix: `${grantName}/`, ContinuationToken: continuationToken })
    );
    for (const object of listed.Contents || []) keys.push(object.Key);
    continuationToken = listed.IsTruncated ? listed.NextContinuationToken : undefined;
  } while (continuationToken);
  return keys;
}

export function copySource(bucket, key) {
  return [bucket, ...key.split("/")].map(encodeURIComponent).join("/");
}

export async function copyArtifacts(s3, fromName, toName) {
  const bucket = artifactsBucket();
  const keys = await listArtifactKeys(s3, fromName);
  for (const key of keys) {
    await s3.send(
      new CopyObjectCommand({
        Bucket: bucket,
        CopySource: copySource(bucket, key),
        Key: `${toName}/${key.slice(fromName.length + 1)}`,
      })
    );
  }
  return keys.length;
}

export async function deleteArtifacts(s3, grantName) {
  const keys = await listArtifactKeys(s3, grantName);
  for (let i = 0; i < keys.length; i += 1000) {
    await s3.send(
      new DeleteObjectsCommand({
        Bucket: artifactsBucket(),
        Delete: { Objects: keys.slice(i, i + 1000).map((Key) => ({ Key })), Quiet: true },
      })
    );
  }
  return keys.length;
}
